import {categories} from './data.js';
import {recipeRepository as repo} from './repository.js';
import {shell,icon,escapeHTML as e,toast,fatal} from './ui.js';
const favoriteOnly=new URLSearchParams(location.search).has('favorites');shell(favoriteOnly?'favorites':'collection');
let category='Усі рецепти';
document.querySelector('#search-icon').innerHTML=icon('search');document.querySelector('#note-icon').innerHTML=icon('book');
if(favoriteOnly)document.querySelector('#collection-title').innerHTML='Моє обране <span id="count" class="count">0</span>';
function render(){const query=document.querySelector('#search').value.trim().toLocaleLowerCase('uk');let all;try{all=repo.list();}catch(err){fatal(err);return;}const collection=all.filter(r=>!favoriteOnly||r.favorite);document.querySelector('#count').textContent=collection.length;const records=collection.filter(r=>(category==='Усі рецепти'||r.category===category)&&[r.title,r.description,...r.ingredients.map(i=>i.name)].join(' ').toLocaleLowerCase('uk').includes(query));const sort=document.querySelector('#sort').value;records.sort(sort==='fast'?(a,b)=>a.time-b.time:sort==='az'?(a,b)=>a.title.localeCompare(b.title,'uk'):(a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''));document.querySelector('#categories').innerHTML=categories.map(c=>`<button class="category ${c===category?'selected':''}" aria-pressed="${c===category}" data-category="${e(c)}">${e(c)}</button>`).join('');document.querySelector('#results-meta').textContent=query||category!=='Усі рецепти'?`Знайдено рецептів: ${records.length}`:'Трохи натхнення для наступного смачного моменту';document.querySelector('#recipe-grid').innerHTML=records.map(r=>`<article class="recipe-card"><a class="card-image ${r.image?'':'no-image'}" href="recipe.html?id=${encodeURIComponent(r.id)}">${r.image?`<img src="${e(r.image)}" alt="${e(r.title)}" loading="lazy">`:`<span class="food-placeholder">${icon('book')}</span>`}<span class="card-category">${e(r.category)}</span></a><button class="favorite ${r.favorite?'is-favorite':''}" data-favorite="${e(r.id)}" aria-pressed="${!!r.favorite}" aria-label="${r.favorite?'Прибрати з обраного':'Додати до обраного'}: ${e(r.title)}">${icon('heart')}</button><div class="card-body"><div class="card-meta">${icon('clock')} ${r.time} хв <span>·</span> ${r.servings} порц.${r.demo?'<span class="demo-mark">Приклад</span>':''}</div><h3><a href="recipe.html?id=${encodeURIComponent(r.id)}">${e(r.title)}</a></h3><p>${e(r.description||'Ваш особливий рецепт. Збережений із любов’ю.')}</p><a class="card-link" href="recipe.html?id=${encodeURIComponent(r.id)}">Готувати ${icon('arrow')}</a></div></article>`).join('')+(!favoriteOnly&&!query&&category==='Усі рецепти'?`<a class="add-card" href="new.html"><span class="add-circle">${icon('plus')}</span><h3>А що готуєте ви?</h3><p>Додайте свій перший рецепт.<br>Найсмачніше ще попереду.</p><span>Записати рецепт ${icon('arrow')}</span></a>`:'');if(!records.length){document.querySelector('#recipe-grid').innerHTML=`<div class="empty"><span>${icon(favoriteOnly?'heart':'search')}</span><h3>${favoriteOnly?'Тут житимуть ваші улюблені рецепти':'Поки нічого не знайшли'}</h3><p>${favoriteOnly?'Натисніть сердечко на рецепті, щоб зберегти його в обране.':'Спробуйте іншу назву, інгредієнт або категорію.'}</p><a href="${favoriteOnly?'index.html':'new.html'}" class="button">${favoriteOnly?'Переглянути рецепти':'Додати рецепт'}</a></div>`;}}
document.querySelector('#categories').addEventListener('click',ev=>{const b=ev.target.closest('[data-category]');if(b){category=b.dataset.category;render();}});
document.querySelector('#recipe-grid').addEventListener('click',ev=>{const b=ev.target.closest('[data-favorite]');if(b){try{repo.toggleFavorite(b.dataset.favorite);render();}catch(err){toast(err.message,true);}}});
document.querySelector('#search').addEventListener('input',render);document.querySelector('#sort').addEventListener('change',render);
document.addEventListener('keydown',ev=>{if(ev.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){ev.preventDefault();document.querySelector('#search').focus();}});
document.querySelector('#export').onclick=()=>{try{const url=URL.createObjectURL(new Blob([JSON.stringify(repo.list(),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`smak-recipes-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Резервну копію завантажено');}catch(err){toast(err.message,true);}};
document.querySelector('#import').onclick=()=>document.querySelector('#import-file').click();document.querySelector('#import-file').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>15000000)throw new Error('Файл завеликий. Максимум — 15 МБ.');repo.import(JSON.parse(await file.text()));render();toast('Рецепти успішно імпортовано');}catch(err){toast(err instanceof SyntaxError?'Не вдалося прочитати JSON-файл.':err.message,true);}ev.target.value='';};
window.addEventListener('storage',render);render();
